void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = texture(iChannel0,fragCoord/iResolution.xy);
}

#define PI 3.1416

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

vec2 rand2(vec2 co) {
    return vec2(
        fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453),
        fract(cos(dot(co, vec2(4.898, 7.23))) * 23421.631)
    );
}

float box(vec3 p, vec3 b) {
    vec3 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0) - 0.1;
}

float kset(vec3 p) {
    p = abs(fract(p * 0.2) - 0.5);
    for (int i = 0; i < 9; i++) {
        p = abs(p) / dot(p, p) - 0.8;
    }
    return p.x + p.y;
}

float det = 0.001;

float de(vec3 p) {
    vec3 p2 = p;
    p.xz *= rot(0.2);
    p.x = abs(p.x);
    p.xz *= rot(2.1);

    float d = box(p, vec3(2.0));
    float der = 1.0;
    float s = 1.3;

    for (float i = 0.0; i < 6.0; i++) {
        p = abs(p * s) - vec3(3.0, 0.3, 2.5);
        p.xy *= rot(radians(90.0));
        p.yz *= rot(radians(90.0));
        der *= s;
        d = min(d, box(p, vec3(0.7, 6.0, 1.0)) / der);
    }

    p = p2;
    der = 1.0;
    for (float i = 0.0; i < 10.0; i++) {
        p = abs(p * s) - vec3(2.0, 0.3, 1.0);
        p.xz *= rot(radians(45.0));
        der *= s;
        d = max(d, -box(p, vec3(1.0, 5.0, 1.5)) / der);
    }

    d += kset(p2) * 0.01;
    d = min(d, p2.y + 2.5);
    return d * 0.7;
}

vec3 normal(vec3 p) {
    vec2 e = vec2(0.0, det);
    return normalize(vec3(
        de(p + e.yxx) - de(p),
        de(p + e.xyx) - de(p),
        de(p + e.xxy) - de(p)
    ));
}

float march(vec3 from, vec3 dir) {
    vec2 uv = gl_FragCoord.xy / iResolution.xy;
    vec3 p = from;
    float col=0., d = 1., maxDist = 100.0, bound = 20.0, hit = 0.0, at=1.;

    for (int b = 0; b < 3; b++) {
        for (int i = 0; i < 100; i++) {
            p += d * dir;
            d = de(p);
            if (d < det || length(p) > bound) break;
        }

        if (d < det) {
            hit = 1.0;
            p -= dir * det * 2.0;
            vec3 n = normal(p);
            vec2 r = rand2(uv + float(iFrame) + n.xy + p.xy);
            vec3 rs = vec3(
                vec2(cos(r.x), sin(r.x)) * sqrt(abs(1.0 - r.y * r.y)),
                r.y
            );
            float rso = dot(n, rs) < 0.0 ? -1.0 : 1.0;
            dir = normalize(rso * rs + n * 0.3);
            d = 0.001;
            at*=.5;
        }

        if (length(p) > bound) {
            col = hit*at*1.5;
            break;
        }
    }

    return col;
}


vec2 uniformDisc(vec2 co) {
    vec2 r = rand2(co);
    return sqrt(r.y) * vec2(cos(r.x * PI * 2.0), sin(r.x * PI * 2.0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    vec2 pix = 1. / iResolution.xy;
    uv += pix * uniformDisc(uv * 0.1 + float(iFrame) * 0.726);
    vec2 uv2 = fragCoord / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;

    vec3 from = vec3(-1.0, 1.0, -16.0);
    vec3 dir = normalize(vec3(uv, 1.0));

    float col = march(from, dir);
    col = pow(col, 1.3);
    col = mix(col, texture(iChannel0, uv2).r, 1.0 - exp(-iTime));

    fragColor = vec4(col);
}
